package dev.zomboid.mts;
import java.util.*;import minecrafttransportsimulator.entities.instances.*;
public class CarGuiChecks {static int n;static void check(boolean b,String s){n++;if(!b)throw new AssertionError(s);}public static void main(String[]args){EntityVehicleF_Physics car=new EntityVehicleF_Physics();PartEngine engine=new PartEngine();engine.vehicleOn=car;car.engines.add(engine);Mechanics.gearDefaults(engine);check(engine.isAutomaticVar.isActive&&engine.getOrCreateVariable("pz_manual_gearbox").currentValue==2,"new engine defaults automatic");engine.getOrCreateVariable("pz_manual_gearbox").setTo(1,false);Mechanics.gearDefaults(engine);check(!engine.isAutomaticVar.isActive,"explicit manual preserved");Mechanics.gearDefaults(engine);check(!engine.isAutomaticVar.isActive,"manual persists next update");car.fuelTank.capacity=2000;car.fuelTank.level=500;check(Mechanics.fuel(car)==.25,"fuel fraction uses tank capacity not stale JSON");check(Workshop.fuelReading(car).contains("0.5 / 2.0 L"),"real fuel amount in litres");Object gui=R.make("dev.zomboid.mts.CheckGUI",car);R.call(gui,"setupComponents");R.call(gui,"setStates");Object region=Workshop.icons.get(gui).get(0);check(((List<?>)R.call(region,"getTooltipText")).get(0).equals("Capo"),"native hover tooltip names actual region");check(((List<?>)R.call(region,"getTooltipText")).get(1).equals("Estado: 100%"),"native hover tooltip includes condition");check(R.get(Workshop.fuelText.get(gui),"text").equals("COMBUSTIBLE 25%"),"fuel prominent in GUI");check(Workshop.fuelBars.get(gui).stream().filter(b->R.yes(R.get(b,"visible"))).count()==6,"bar matches quarter-full tank");check(R.get(Workshop.modeButtons.get(gui),"text").toString().contains("MANUAL"),"current gearbox visible");car.fuelTank.level=0;R.call(gui,"setStates");check(R.get(Workshop.fuelAmount.get(gui),"text").toString().startsWith("Vacio"),"empty tank labelled clearly");check(Workshop.fuelBars.get(gui).stream().noneMatch(b->R.yes(R.get(b,"visible"))),"empty tank has no filled bar");R.call(gui,"close");check(!Workshop.fuelBars.containsKey(gui)&&!Workshop.modeButtons.containsKey(gui),"car GUI state released");System.out.println("Car GUI checks: "+n);}}
